  StageGroup_118157_Desc = {
    Text = "বৃহৎ ক্রুজ জাহাজ “প্যারাডাইস” হলো সাগরচারীদের অর্ডারের নিবাস, যারা সীমাহীন সাগর পাড়ি দেয়。\nতোমার মনোবাঞ্ছা এই জাহাজে অর্পণ করো, আর যে সুখ তুমি খুঁজছ, তার শেষ আর থাকবে না।"
