  StageGroup_120951_Desc = {
    Text = "মাত্রার অন্য প্রান্ত থেকে, বহুদিনের হারানো গৃহের এক ক্ষীণ অথচ অস্বীকারহীন আহ্বান আমাদের ডেকে চলেছে。\nসর্বোচ্চ সত্তার চেতনা থেকে উদ্ভূত ধ্বংসের দৃষ্টি আবারও আমাদের উপর স্থির হয়েছে। আমাদের তাকে ঠেকাতে হবে, অমান্য করতে হবে, দূরবর্তী সময়-স্থান ভাঁজ পেরিয়ে আবারও একত্রিত হতে হবে。\nএই দীর্ঘ, অন্ধকার যাত্রাপথে, সেই একটিমাত্র প্রতিশ্রুতিই হবে আমাদের একমাত্র পথপ্রদর্শক আলো।"
  },
  StageGroup_120951_Name = {
