  StageGroup_122187_Desc = {
    Text = "আমার সন্তান, যন্ত্রণা ও শোক এক কুয়াশার মতো তোমার চোখ ঢেকে রেখেছে। কিন্তু বিচলিত হয়ো না; যদি তুমি নিজেকে রক্ষা করতে চাও, তবে সর্বপিতা অবশ্যই তোমাকে সহায় হবেন এবং তোমাকে বাপ্তিস্ম দান করবেন—যদিও তা সিলভার আর রক্তের মাধ্যমেই হোক।"
