    Text = "অবসিডিয়ান মাতৃতন্ত্র"
  },
  StageGroup_125338_Desc = {
    Text = "রাস্তার বাতিগুলো মিটমিট করে জ্বলে ওঠে, আর শহর ডুবে যায় নির্জনতার গহ্বরে।\nএবার দেখো—ওই অপূর্ব চোখ দুটির গভীরে দৃষ্টি ডুবিয়ে দাও।\nতারপর, অনুগ্রহের সঙ্গে আত্মসমর্পণ করো; অনুগ্রহের সঙ্গে হেঁটে গিয়ে হামাগুড়ি দাও; অনুগত পায়ে পা ফেলে ঢুকে পড়ো সেই অবশিষ্ট রাতের কুয়াশার ভেতর।"
