  StageGroup_125684_Desc = {
    Text = "কিঁচ্‌কিঁচ্—কিঁচ্‌কিঁচ্—ভাগ্যের দেবী তাঁর চরকা ঘোরান।\nকিঁচ্‌কিঁচ্—কিঁচ্‌কিঁচ্—ভাগ্যের সুতো তাঁর হাতে জড়ো হয়।\nপুতুলেরা সারি বেঁধে প্রবেশ করে, ভাগ্যের বিশাল জালে পা রাখে।\nতারা নাচে। তারা গান গায়। কিঁচ্‌কিঁচ্—কিঁচ্‌কিঁচ্—\nতারা সেই জালের সাথেই মরে যায়, নিঃশব্দে।"
  },
