  StageGroup_129506_Desc = {
    Text = "স্বদেশ, মধুর স্বদেশ।\nপানলং সাম্রাজ্যের রীতিনীতি অনুযায়ী, বছরের শুরুতে যারা স্বদেশ ছেড়ে গেছে, সেই বালকেরা ভোরের কুয়াশা আর দূরবর্তী পর্বতমালা ভেদ করে জনতায় ঠাসা ট্রেনে চেপে বসে, দীর্ঘ বিচ্ছেদের পর প্রিয়জনদের তোষামোদকারীর আলিঙ্গনে ফিরে আসার জন্য।\nতুমিও এর ব্যতিক্রম নও।"
