  StageGroup_130895_Desc = {
    Text = "লোভীদের ওপর আরও বর্ষিত হয়; যারা সহজে তৃপ্ত, তাদের হাত থেকে একসময় যা কিছু ছিল, সবই ছিনিয়ে নেওয়া হয়।\nআমরা যখন সাগরের দিকে তাকাই, কেবল তার বিস্তার আর সৌন্দর্যের দিকে তাকাই না; সাগর গিলে নেয় স্মৃতিচারণ, সাগর গিলে নেয় ভয়, আর তার স্রোতগুলোর সব সংযোগ বিন্দু এক নিমেষে বিলীন হয়ে যায়।\nসাগর তোমাকে ডাকে, নীরবতার চিরন্তন নিঃসঙ্গতায় ডুবে যেতে।"
  },
