  StageGroup_145355_Name = {
    Text = "শূন্য দর্পণ"
  },
  StageGroup_145355_TypeText = {
    Text = "রক্তলোভী প্রতিযোগিতা"
  },
  StageGroup_145356_Desc = {
    Text = "বারো হাজার বছরের প্রহরায় লেভিয়াথান অনেক আগেই ক্লান্ত হয়ে পড়েছে।\nরাজারা তাঁর পায়ের নিচে অভিষিক্ত হয়েছে, সাধুরা তাঁর সামনে লোভী হয়ে উঠেছে, বীরেরা নির্বিকারে তাঁর অসীম ক্ষমতার লালসায় অবগাহন করেছে। রক্তস্নাত মুকুট খসে পড়েছে, এক মাথা থেকে আরেক মাথায়।\nতিনি সেই একঘেয়ে নাটকগুলো চিবিয়ে খেয়েছেন, যেন নক্ষত্রনদীর নিরস ধূলিকণা গ্রাস করছেন। তিনি ভেবেছিলেন, এটাই তাঁর চিরন্তন জীবনে দেখার সব কিছু।\nযতক্ষণ না সে তাঁর সামনে এলো।"
  },
  StageGroup_145356_Name = {
    Text = "যতক্ষণ তিমি-আকাশ পতিত না হয়"
  },
  StageGroup_145356_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_145357_Name = {
    Text = "খাঁচাবন্দী পশু"
  },
  StageGroup_145357_TypeText = {
    Text = "রক্তলোভী প্রতিযোগিতা"
  },
  StageGroup_145358_Name = {
