  StageGroup_145360_TypeText = {
    Text = "রক্তলোভী প্রতিযোগিতা"
  },
  StageGroup_146256_Desc = {
    Text = "পর্বতমালা বিশ্বের শেষ প্রান্তে দাঁড়িয়ে আছে।\nচিরতুষারাবৃত বিস্তীর্ণ বরফের উপর, প্রাচীন ক্ষুধা দীর্ঘ গভীর নিদ্রা থেকে জাগরণ লাভ করছে।\nপর্বত তার বিশাল রক্তাক্ত মুখ হাঁ করে, গভীর ও বিদ্রূপাত্মক হাসিতে ফেটে পড়ে।\nধৈর্য ধরে প্রহরা করো—প্রার্থনাকারীরা ইতিমধ্যে ভোজের পথে রওনা হয়েছে।"
  },
  StageGroup_146256_Name = {
    Text = "পর্বত ভোজ"
  },
  StageGroup_146256_TypeText = {
    Text = "তদন্তের জটিলতা"
  },
  StageGroup_146257_Desc = {
    Text = "পর্বতমালা বিশ্বের শেষ প্রান্তে দাঁড়িয়ে আছে।\nচিরতুষারাবৃত বিস্তীর্ণ বরফের উপর, প্রাচীন ক্ষুধা দীর্ঘ গভীর নিদ্রা থেকে জাগরণ লাভ করছে।\nপর্বত তার বিশাল রক্তাক্ত মুখ হাঁ করে, গভীর ও বিদ্রূপাত্মক হাসিতে ফেটে পড়ে।\nধৈর্য ধরে প্রহরা করো—প্রার্থনাকারীরা ইতিমধ্যে ভোজের পথে রওনা হয়েছে।"
  },
  StageGroup_146257_Name = {
    Text = "পর্বত ভোজ"
  },
  StageGroup_146257_TypeText = {
    Text = "তদন্ত"
  },
  StageGroup_146787_Desc = {
    Text = "যে প্রজন্ম চলে গেছে, কেউ তাদের স্মরণ করে না, আর যে প্রজন্ম আসবে, পরবর্তী মানুষেরাও তাদের স্মরণ করবে না।\nবিগত দিনের প্রতি আসক্তি যেন বায়ু ধরার চেষ্টা, তাই আমি জীবনকে ঘৃণা করি।"
  },
