  StageGroup_15871_Desc = {
    Text = "তারা অন্ধকারে পেঁচিয়ে গিয়ে একে অন্যের সঙ্গে মিশে যায়, তারপর মূর্তিগুলোর ভেতরে যত্নে সংরক্ষিত হয়।\nএটি এক পূর্বপরিকল্পিত পুনর্মিলন।"
