  StageGroup_15871_TypeText = {
    Text = "আল্ট্রা যাত্রা"
  },
  StageGroup_15872_Desc = {
    Text = "তারা সময় ও স্থান-এর ফাঁকফোকর বেয়ে ভেসে বেড়ায়, দুর্বোধ্য জাদুকরের মতো।\nনা ঘৃণা, না ভয়, না দয়া।"
  },
  StageGroup_15872_Name = {
    Text = "মহাজাগতিক অবশেষ"
  },
  StageGroup_15872_StageGroupRewardDescription = {
    Text = "<Black:এডিফাই উপকরণ>"
  },
  StageGroup_15872_TypeText = {
    Text = "মহাজাগতিক অবশেষ"
  },
  StageGroup_15873_Desc = {
    Text = "লন্ডিনিয়াম তার দ্যুতিময় শিল্পসভ্যতা এবং শহরকে আচ্ছন্ন করে রাখা সীসাভারী কুয়াশার জন্য সুবিখ্যাত।\nকুয়াশা সর্বত্র—পথচারীদের কাছে, তা কেবলই এক আকস্মিক, অর্থহীন অসুবিধা মাত্র।"
  },
  StageGroup_15873_Name = {
    Text = "বিচিত্র কুয়াশার নগরী"
  },
  StageGroup_15873_StageGroupRewardDescription = {
    Text = "<Black:কভেন্যান্ট>"
  },
  StageGroup_15873_TypeText = {
    Text = "বিচিত্র কুয়াশার নগরী"
  },
  StageGroup_15874_Desc = {
    Text = "তারা অন্ধকারে পেঁচিয়ে গিয়ে একে অন্যের সঙ্গে মিশে যায়, তারপর মূর্তিগুলোর ভেতরে যত্নে সংরক্ষিত হয়।\nএটি এক পূর্বপরিকল্পিত পুনর্মিলন।"
  },
  StageGroup_15874_Name = {
    Text = "কেওসের ক্ষেত্র"
  },
  StageGroup_15874_TypeText = {
    Text = "কেওসের ক্ষেত্র"
  },
  StageGroup_15875_Desc = {
    Text = "প্রতিটি বৃষ্টিভেজা রাতই খুনের এক ফিসফিসানি নিয়ে আসে。\nএইবার, তুমি একাই রওনা হয়েছ রাই-এর উত্তরে অবস্থিত রেনি টাউনে, এক অদ্ভুত কেসের অনুসন্ধানে..."
  },
  StageGroup_15875_Name = {
    Text = "বৃষ্টিময় শহরের ছায়ামূর্তি"
  },
  StageGroup_15875_TypeText = {
    Text = "বিশেষ অপস"
  },
  StageGroup_15876_Desc = {
    Text = "「সে এক। সে সর্ব। সে সেই আশা, যে সত্যের দ্বার উন্মুক্ত করে।」\nঅগণিত চাবি একটি বৃত্ত রচনা করে। তারা আকাশ থেকে ঝরে পড়ে, মানবতার জন্য বয়ে আনে এক ভারী আশা।\nআর ভারী কবর।"
  },
  StageGroup_15876_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15876_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15877_Desc = {
    Text = "「প্রতিটি চাবির নিজস্ব একক নম্বর আছে, যা কেবলমাত্র একটি অনুসন্ধান কর্মকর্তার সঙ্গেই সঙ্গতিপূর্ণ।「\n「অতএব, প্রতিটি চাবির পতন মানে একটি অনুসন্ধান কর্মকর্তার মৃত্যু।「\n「কী অপূর্ব। এমনকি তাদের মৃত্যুও অনন্য।「"
  },
  StageGroup_15877_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15877_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15878_Desc = {
    Text = "কিলবিল, সেঁধিয়ে যাওয়া... প্রোটোপ্লাজমিক পিণ্ডটি তার শৃঙ্খল-এর ফাটল বেয়ে গলে বেরিয়ে আসে।\n「স্বাধীনতা」-র জন্য এটাই তার চুকানো মূল্য।"
  },
  StageGroup_15878_Name = {
    Text = "অন্ধকারের শৃঙ্খল"
