  },
  StageGroup_15879_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15880_Desc = {
    Text = "「হাত」 রাত্রির পর্দা সরিয়ে তোলে, নীরবে এই জগতে আগমন করে।"
