  StageGroup_15887_TypeText = {
    Text = "রক্তাক্ত অবশেষ"
  },
  StageGroup_15888_Desc = {
    Text = "সরকারি নথি অনুযায়ী, @1তম পবিত্র ক্রুসেডে তিন হাজারেরও বেশি মানুষ অংশ নিয়েছিল।\nক্রুসেডারদের উদ্দেশ্য ছিল নানান: কেউ খুঁজেছিল জীবিকা, কেউ খুঁজেছিল প্রতিশোধ।\nআর কেউ খুঁজেছিল নিছক হত্যাযজ্ঞ।"
