  StageGroup_15890_TypeText = {
    Text = "তদন্ত"
  },
  StageGroup_15891_Desc = {
    Text = "এখানে নিদ্রামগ্ন এক প্রাচীন নগরের ধ্বংসাবশেষ শুয়ে আছে।\nএটি তার প্রভুর মতোই গভীর ঘুমে আচ্ছন্ন।"
