  StageGroup_15892_Desc = {
    Text = "তারা ছিল অচেতন এক মিশ্রণ—শোক, বিকৃতি আর সরলতার,\nযাদের সাজানো হয়েছে আনন্দিত বালকেরা, প্রাপ্তবয়স্ক আর পোষা প্রাণীর বেশে।\nকখনো সুখ না-চেখে, তারা হয়ে উঠেছে সবচেয়ে করুণ অভিনেতা।"
  },
