  StageGroup_15909_Desc = {
    Text = "এটি বিন্দুমাত্র বিরতি না নিয়ে অপরাধীদের পিছু ধাওয়া করে।\nকিন্তু 「নিয়ম」 কাকে বলে, আর কী-ই বা 「ভঙ্গ」 করা?\nশিকারি কুকুরটি কখনো ভাবনা-চিন্তা করে না—তাতে কেবল ধাওয়া মন্থর হয়ে যাবে।"
