  StageGroup_15930_TypeText = {
    Text = "কারোর জলাভূমি"
  },
  StageGroup_15931_Desc = {
    Text = "তারা অন্ধকারে পেঁচিয়ে গিয়ে একে অন্যের সঙ্গে মিশে যায়, তারপর মূর্তিগুলোর ভেতরে যত্নে সংরক্ষিত হয়।\nএটি এক পূর্বপরিকল্পিত পুনর্মিলন।"
  },
  StageGroup_15931_Name = {
    Text = "কারোর জলাভূমি"
  },
  StageGroup_15931_TypeText = {
    Text = "কারোর জলাভূমি"
  },
  StageGroup_15932_Desc = {
    Text = "লিও রাজ্যের উত্তর সাগর শান্ত ও কোমল এক মধ্যগ্রীষ্ম ধারণ করে।\nতার শীতকাল বাহ্যত শান্ত ও পরিশীলিত, তবু সেই সুন্দর দীপ্তিময় মেঘের নীচে লুকিয়ে থাকে মরণঘাতী ঝড়।"
  },
  StageGroup_15932_Name = {
    Text = "ঝড়ের বহিঃসাগর"
  },
  StageGroup_15932_StageGroupRewardDescription = {
    Text = "<Black:কভেন্যান্ট>"
  },
  StageGroup_15932_TypeText = {
    Text = "ঝড়ের বহিঃসাগর"
  },
  StageGroup_15933_Desc = {
    Text = "সমস্ত জাগরণকারী স্তর, দক্ষতার স্তর, এবং অবশেষের শক্তি 1 স্তরে নির্ধারিত।\nঅনুরণন সমন্বয় ইচ্ছামতো বেছে নেওয়া যাবে; সমন্বয়ের তারকা-মান যত উচ্চ, সমাপ্তির পর পুরস্কার তত বেশি।"
  },
  StageGroup_15933_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15933_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15934_Desc = {
    Text = "「সে এক। সে সর্ব। সে সেই আশা, যে সত্যের দ্বার উন্মুক্ত করে।」\nঅগণিত চাবি একটি বৃত্ত রচনা করে। তারা আকাশ থেকে ঝরে পড়ে, মানবতার জন্য বয়ে আনে এক ভারী আশা।\nআর ভারী কবর।"
  },
  StageGroup_15934_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15934_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15935_Desc = {
    Text = "এই বিদায়ের দিনে, হালকা ঝিরিঝিরি বৃষ্টি পড়ছে কীগ্রেভের ওপর।\nএখানেই তুমি সমাধিস্থ করবে তোমার সমাধিফলক, তোমার নাম, আর তোমার শপথ।"
  },
  StageGroup_15935_Name = {
    Text = "ভর্তি দিবস"
  },
  StageGroup_15935_TypeText = {
    Text = "তদন্ত"
  },
  StageGroup_15936_Desc = {
    Text = "তারা অস্তিত্বশীল ছিল নক্ষত্রপুঞ্জের জন্মের বহু আগেই।\nতারা একই সঙ্গে মায়াস্বপ্ন এবং সবকিছু।"
  },
  StageGroup_15936_Name = {
    Text = "ঘোলাটে অবশিষ্টাংশ"
  },
  StageGroup_15936_StageGroupRewardDescription = {
    Text = "<Black:এডিফাই উপকরণ>"
  },
  StageGroup_15936_TypeText = {
    Text = "ঘোলাটে অবশিষ্টাংশ"
  },
  StageGroup_15937_Desc = {
    Text = "এখানে সমাধিস্থ এক বিশ্ববিদ্যালয়, ভাঙাচোরা ও ক্ষতবিক্ষত, সমস্ত শক্তি শুষে নেওয়া হয়েছে\nএকদা, মানবতার দীপ্তি টিকিয়ে রাখার জন্য সে সাহস করে এক ক্ষীণ গ্লিমার উপহার দিয়েছিল\nতার পরিণতি—এখন তোমার চোখের সামনেই।"
  },
  StageGroup_15937_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15937_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15938_Desc = {
    Text = "ধসে পড়া মূর্তি তার জনগণকে নির্নিমেষে দেখে;\nতাদের টিকে থাকা, বংশবৃদ্ধি, সংঘাত—আর সময়ের সঙ্গে সঙ্গে তাকে সম্পূর্ণ ভুলে যাওয়া—সবই সে দেখে।\nধসে পড়া মূর্তি তার জনগণকে আকুল হয়ে কামনা করে..."
  },
  StageGroup_15938_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15938_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15939_Desc = {
    Text = "「প্রতিটি চাবির নিজস্ব একক নম্বর আছে, যা কেবলমাত্র একটি অনুসন্ধান কর্মকর্তার সঙ্গেই সঙ্গতিপূর্ণ।「\n「অতএব, প্রতিটি চাবির পতন মানে একটি অনুসন্ধান কর্মকর্তার মৃত্যু।「\n「কী অপূর্ব। এমনকি তাদের মৃত্যুও অনন্য।「"
  },
  StageGroup_15939_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15939_TypeText = {
