  StageGroup_15945_Desc = {
    Text = "এটি অনুগত বিশ্রাম ও পুনরুদ্ধার-এ শয্যার পাশে হেলান দিয়ে আছে, তার ম্লান বোতাম-চোখ শূন্যতার দিকে স্থির।\nক্ষুদ্র দেহটি তার মালিকের সব অশ্রু বহন করেছে, তবু একটিও সান্ত্বনার শব্দ দিতে অক্ষম।"
