  },
  StageGroup_15957_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_15958_Desc = {
    Text = "রজার্স মোম জাদুঘর সাউথওয়ার্ক স্ট্রিট-এর একেবারে শেষ প্রান্তে, টেম-এর এক উপনদীর ধারে বসে আছে।\nবাহ্যিক চেহারায় অনাড়ম্বর, তবু এটি দূর থেকে আগত অ্যাভান্ট-গার্ড আর্ট-এর অনুরাগীদের টেনে আনে।"
