  StageGroup_15959_TypeText = {
    Text = "কারোর জলাভূমি"
  },
  StageGroup_15960_Desc = {
    Text = "সরকারি নথি অনুযায়ী, @1তম পবিত্র ক্রুসেডে তিন হাজারেরও বেশি মানুষ অংশ নিয়েছিল।\nক্রুসেডারদের উদ্দেশ্য ছিল নানান: কেউ খুঁজেছিল জীবিকা, কেউ খুঁজেছিল প্রতিশোধ।\nআর কেউ খুঁজেছিল নিছক হত্যাযজ্ঞ।"
  },
  StageGroup_15960_Name = {
    Text = "রক্ত ও বালি"
  },
  StageGroup_15960_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_20222_Desc = {
    Text = "দাসী কামিলকে পাঁচ বছর বয়সে মিস সাংগার সামনে আনা হয়েছিল।\nসাংগা ছিল ভাস্কর্যের মতো সুন্দর ও দূরবর্তী। সূর্যালোকে সে কামিলের দিকে তাকিয়ে হাসল।\nসেই দিন থেকেই কামিল একটি ইচ্ছে পোষণ করল: চিরকাল একসঙ্গে থাকা।"
  },
  StageGroup_20222_Name = {
    Text = "গানের মতো রূপায়িত"
  },
  StageGroup_20222_TypeText = {
