  StageGroup_20446_Desc = {
    Text = "কথিত আছে, লন্ডিনিয়ামের বহু গভীরে আছে একটি মাত্র দ্বার।\nওপারে রয়েছে বিবর্ণ অধিশ্বরীর ডোমেইন।"
  },
  StageGroup_20446_Name = {
    Text = "বিবর্ণ উত্তরসূরি"
  },
  StageGroup_20446_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_20447_Desc = {
    Text = "সে একটি অটোমেটন, যাকে মিথাগ বিশ্ববিদ্যালয় পুনরুদ্ধার করেছে।\nতার কঙ্কাল ধাতব, তার হৃদয় এক সিলভার কোর। তার নির্মাণ এমনই সূক্ষ্ম যে সমস্তের উৎস নকশা থাকলেও, দ্বিতীয়টি কখনও তৈরি করা যাবে না।\nশীতল ঘড়ির কাঁটা হওয়ার আগে, তার ছিল এক মানবিক হৃদয়।"
  },
  StageGroup_20447_Name = {
    Text = "বিকৃত কেন্দ্র"
  },
  StageGroup_20447_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_20448_Desc = {
    Text = "সে একটি অটোমেটন, যাকে মিথাগ বিশ্ববিদ্যালয় পুনরুদ্ধার করেছে।\nতার কঙ্কাল ধাতব, তার হৃদয় এক সিলভার কোর। তার নির্মাণ এমনই সূক্ষ্ম যে সমস্তের উৎস নকশা থাকলেও, দ্বিতীয়টি কখনও তৈরি করা যাবে না।\nশীতল ঘড়ির কাঁটা হওয়ার আগে, তার ছিল এক মানবিক হৃদয়।"
  },
  StageGroup_20448_Name = {
