  },
  StageGroup_20449_Desc = {
    Text = "আত্মা ও হৃদয়ের অনুরণন তোমাকে তাদের স্মৃতিচারণে প্রবেশ করতে দেয়, তাদের স্বপ্নে পা রাখতে দেয়।\nবাঁচো প্রেম ও যন্ত্রণার ভেতর দিয়ে; দেখো মহিমা ও কোমলতা। তবেই তুমি অনুভূতির ব্যাপ্তি সত্যিই অনুধাবন করবে।"
