  },
  StageGroup_51755_Desc = {
    Text = "একটি সাগরের মৃত্যু ঘটল; তার অবশিষ্ট দেহকে সে নিজ হাতে সমাধিস্থ করল।\nঅন্ধকার অতল সাগরের আয়নার উপর, তার রাজার স্বপ্ন বিলীন হয় এবং দেবলোক পচে গিয়ে ভেঙে পড়ে।\nসে দেখে, এক প্রাচীন স্বপ্নের ভেতর থেকে নিজেকে এগিয়ে আসতে, কেবলই ভেঙে পড়া ভবিষ্যতের ধ্বংসস্তূপের দিকে পা বাড়াতে।\nসে অতলকে জিজ্ঞাসা করে, কিন্তু অতল নীরব থাকে।\nসে অতলকে উৎসর্গ অর্পণ করে, কিন্তু যে একমাত্র কণ্ঠ প্রতিধ্বনিত হয়, তা তার নিজেরই।"
  },
  StageGroup_51755_Name = {
    Text = "অপবিত্রকরণ"
  },
  StageGroup_51755_TypeText = {
    Text = "স্বপ্নদৃশ্য"
  },
