  StageGroup_55453_Desc = {
    Text = "সব শব্দ ছাই হয়ে গেছে; সব পাপড়ি কাদায় মিশে গেছে।\nমৃতপ্রায় বাগানের শেষ উষ্ণ নিশ্বাস টেনে, তোমাকে আরেকটি কবিতা শোনাই।\nআমাদের উজাড় হৃদয়ে, গোলাপেরা বাস করে গাঢ় লাল রঙে।"
  },
