  },
  StageGroup_56440_Desc = {
    Text = "রক্ষক অনিচ্ছাকৃতভাবে পা বাড়ায় 「তাঁর」 পাতানো খেলায়।\nরক্তিম চাঁদ, প্রাচীন প্রাসাদ, তুষারঝড়, আর গোপন অভিসন্ধি লুকিয়ে রাখা অংশগ্রহণকারীরা...\nমনের ও হৃদয়ের দ্বন্দ্ব শুরু হয় সঙ্গে সঙ্গেই।"
  },
  StageGroup_56440_Name = {
    Text = "শুভ শিকার!"
  },
  StageGroup_56440_TypeText = {
    Text = "বিশেষ অপস"
  },
  StageGroup_56441_Desc = {
    Text = "রক্ষক অনিচ্ছাকৃতভাবে পা বাড়ায় 「তাঁর」 পাতানো খেলায়।\nরক্তিম চাঁদ, প্রাচীন প্রাসাদ, তুষারঝড়, আর গোপন অভিসন্ধি লুকিয়ে রাখা অংশগ্রহণকারীরা...\nমনের ও হৃদয়ের দ্বন্দ্ব শুরু হয় সঙ্গে সঙ্গেই।"
  },
  StageGroup_56441_Name = {
    Text = "শুভ শিকার!"
  },
  StageGroup_56441_TypeText = {
    Text = "বিশেষ অপস"
  },
  StageGroup_56443_Desc = {
    Text = "ঘন তুষার ঢেকে দেয় পর্বতমালার নীরব নিশ্বাস, আর প্রতিটি প্রত্যাবর্তনকারী আত্মা যে নিয়তি তাড়া করে তা-ও।\nচির-বরফাবৃত এলওয়ার্থে, এক যোদ্ধা তার তলোয়ার তোলে।\nযার জন্য সে লড়ে, তা তার জীবনের প্রথম বসন্ত।"
  },
