  StageGroup_58900_Desc = {
    Text = "প্রবেশ করো। বসো। অপেক্ষা করো। আকুল হও।\nনরম ভঙ্গিতে ওঠে সুরের দণ্ড। তুমি কি প্রস্তুত, মহাবিশ্বের গভীরতম রহস্য শোনার জন্য?"
