  StageGroup_67785_Desc = {
    Text = "তার একটি দীর্ঘ স্বপ্ন ছিল।\nসে স্বপ্ন দেখেছিল দেবতা আর তারার; ধুলো থেকে সভ্যতার জন্ম, আর সভ্যতার ধুলোয় ফিরে যাওয়া।\nসে স্বপ্ন দেখেছিল ঘৃণা আর ভালোবাসার; আনন্দ আর ভয়ের।\nহঠাৎ চমকে উঠে তার ঘুম ভাঙল। তার স্বপ্নের সবকিছু—কখনোই ছিল না।"
  },
  StageGroup_67785_Name = {
    Text = "দীর্ঘ স্বপ্নের সমাপ্তি"
  },
  StageGroup_67785_TypeText = {
