  },
  StageGroup_70938_Desc = {
    Text = "সমষ্টিগত অবচেতন মনের গড়া এক স্যানাটোরিয়াম।\nএখানে খোলসের ডিজলিউশন শেষ নয়; শেষ হচ্ছে মনের মৃত্যুতে।\nযারা প্রবেশ করবে, অনুগ্রহ করে তোমার সুস্থতা অটুট রেখো। নিজের মনের গোলকধাঁধা পেরোতে গিয়ে তোমার একমাত্র ভরসা হবে তোমার মানবতার দীপ্তি।"
  },
  StageGroup_70938_Name = {
    Text = "রূপান্তর"
  },
  StageGroup_70938_TypeText = {
    Text = "তদন্ত"
  },
  StageGroup_70939_Desc = {
    Text = "ধূসর কুয়াশার গর্ভে চাপা পড়ে আছে এক প্রাচীন নগরের ধ্বংসাবশেষ।\nআলোহীন নক্ষত্রের শূন্যতা পেরিয়ে যাও, ক্ষতবিক্ষত মাত্রা-জুড়ে পরম ইচ্ছাশক্তি‑র বিচ্ছিন্ন চিন্তাখণ্ডের সঙ্গে পুনর্মিলিত হতে।"
  },
  StageGroup_70939_Name = {
    Text = "কুয়াশা নগরে প্রত্যাবর্তন"
  },
  StageGroup_70939_TypeText = {
    Text = "তদন্ত"
  },
  StageGroup_70940_Desc = {
    Text = "আনন্দ করো, আমার বন্ধু♪\nচাঁদের আলোয়, হাড়েরা নীরবে প্রস্ফুটিত হয়♪\nআমার প্রিয় শুয়ে আছে নিশ্চল, রূপালি থালার বুকে♪\nসব অতিথি এসে গেছে♪গাও! নাচো! এখন আরাধনা করি!♪\nকখনো লাশের জন্য শোক কোরো না♪কখনো মৃতদের জন্য প্রার্থনা কোরো না♪\nতার স্মৃতিচারণ আমার হাতে♪তার অশ্রু আমার দাঁতে♪\nচলো গিলে ফেলি তার আত্মা, তার মাংস এতই মিষ্টি♪\nআমাদের মৃত্যুর ভোজসভায়, যেখানে প্রিয়জনেরা মিলিত হয়♪"
  },
  StageGroup_70940_Name = {
    Text = "অস্থিভোজ উৎসব"
  },
  StageGroup_70940_TypeText = {
    Text = "তদন্ত"
  },
  StageGroup_71850_Desc = {
    Text = "গৌরব, ভক্তি, সীমাহীন শক্তি—সিংহাসন দাঁড়িয়ে আছে সকলের ঊর্ধ্বে।\nতাতে আরোহণের জন্য প্রয়োজন কেবল দেবতার নির্বাচিত হওয়া।\nতবু এর বিনিময়ে কী মূল্য চুকোতে হয়?"
  },
