  },
  StageGroup_74236_Desc = {
    Text = "সেই রাতে, যখন আকাশ অগ্নিশিখায় দাউদাউ করে জ্বলছিল, তখন শুধু তার শিল্পই পুনর্জন্ম লাভ করেনি।"
  },
  StageGroup_74236_Name = {
    Text = "আবেগ ধূলিসাৎ"
  },
  StageGroup_74236_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_74237_Desc = {
    Text = "সেই রাতে, যখন আকাশ অগ্নিশিখায় দাউদাউ করে জ্বলছিল, তখন শুধু তার শিল্পই পুনর্জন্ম লাভ করেনি।"
  },
  StageGroup_74237_Name = {
    Text = "আবেগ ধূলিসাৎ"
  },
  StageGroup_74237_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_74238_Desc = {
    Text = "সেই রাতে, যখন আকাশ অগ্নিশিখায় দাউদাউ করে জ্বলছিল, তখন শুধু তার শিল্পই পুনর্জন্ম লাভ করেনি।"
  },
  StageGroup_74238_Name = {
    Text = "আবেগ ধূলিসাৎ"
  },
  StageGroup_74238_TypeText = {
    Text = "মানসের গভীর অবগাহন"
  },
  StageGroup_74338_Desc = {
    Text = "এক রহস্যময় উপস্থিতি এসে পৌঁছেছে ট্র্যাফেজে—শিংওয়ালা এক মেয়ে সকলের সামনে বাজি ছুড়ে দিল।\nশিশিরবিন্দু সংগ্রহ করো, শক্তিশালী প্রতিদ্বন্দ্বীদের পরাজিত করো, সবই আবারও একবার স্থানকে উল্টে দেওয়ার জন্য।\nযখন আকাশ চিরে নামা সিলভার আলো সবকিছুকে আলোকিত করা জ্বলন্ত সূর্যকে ভেঙে চুরমার করে দেয়, তখন মেয়েটি অবশেষে বুঝতে পারে।\nযা সে কখনোই ছাড়তে পারেনি, তা হলো অতীতে গেঁথে থাকা এক গভীর আবেশ।\nশৃঙ্খল ভেঙে গেলে, আবেশ ঝরে পড়লে, যাত্রার অন্তিম প্রান্তে পৌঁছানো সেই মেয়ে তার বন্ধুদের প্রতি সবচেয়ে আন্তরিক আশীর্বাদ নিবেদন করে।"
  },
  StageGroup_74338_Name = {
    Text = "আমার পালা"
  },
  StageGroup_74338_TypeText = {
    Text = "বহুমাত্রিক সংযোগ"
  },
  StageGroup_75263_Desc = {
    Text = "এখানে সমাধিস্থ এক বিশ্ববিদ্যালয়, ভাঙাচোরা ও ক্ষতবিক্ষত, সমস্ত শক্তি শুষে নেওয়া হয়েছে\nএকদা, মানবতার দীপ্তি টিকিয়ে রাখার জন্য সে সাহস করে এক ক্ষীণ গ্লিমার উপহার দিয়েছিল\nতার পরিণতি—এখন তোমার চোখের সামনেই।"
  },
  StageGroup_75263_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_75263_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_75264_Desc = {
    Text = "ধসে পড়া মূর্তি তার জনগণকে নির্নিমেষে দেখে;\nতাদের টিকে থাকা, বংশবৃদ্ধি, সংঘাত—আর সময়ের সঙ্গে সঙ্গে তাকে সম্পূর্ণ ভুলে যাওয়া—সবই সে দেখে।\nধসে পড়া মূর্তি তার জনগণকে আকুল হয়ে কামনা করে..."
  },
  StageGroup_75264_Name = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_75264_TypeText = {
    Text = "মায়াবী অবগাহন"
  },
  StageGroup_75265_Desc = {
