  StageGroup_88933_Name = {
    Text = "অন্তহীন বালু"
  },
  StageGroup_88933_TypeText = {
    Text = "আকাশচুম্বী আত্মা"
  },
  StageGroup_88934_Desc = {
    Text = "এটি পাখিদের আকাশগানের এক ব্যালাড:\nবাইরের জগতে কী লুকিয়ে আছে? দূর দিগন্তের কি কোনো শেষ আছে?\nসেখানে কি থাকবে বিশ্বস্ত নাইট আর সুন্দরী রাজকুমারী?\nআছে কি সীমাহীন তৃণভূমি, প্রতীক্ষমাণ দুরন্ত অশ্ব?\nযাও—নিজ চোখে দেখে এসো।\nআজ, যাত্রার সূচনা।"
  },
  StageGroup_88934_Name = {
