  StageGroup_91021_Desc = {
    Text = "এই যুদ্ধ গড়া হয়েছে ক্ষুধার গলনচুল্লিতে।\nযোদ্ধার শপথে আমরা বলি: সবচেয়ে তুচ্ছ রান্নাঘরও আমাদের ক্ষুধার কাছে মাথা নত করবে!"
