  StageGroup_94850_Desc = {
    Text = "অদ্ভুত সুন্দর কল্পনা সবসময়ই বালকের বিশেষাধিকার বলে বিবেচিত হয়, তাই বাস্তবতার নিয়ম থেকে তা নির্বাসিত। কিন্তু নিষ্ঠুর পৃথিবীর মুখোমুখি হওয়ার আগে, তুমি এখানে থাকা সবকিছু সাময়িকভাবে ভুলে যেতে রাজি।"
