  StageGroup_95184_Desc = {
    Text = "অ্যাম্বার রঙের শিখা শবযাত্রার মতো জাঁকজমকে প্রস্ফুটিত হয়।\nদাবানলের প্রভু জন্ম নেয় মৃত্যুর ভস্ম থেকে, যেখানে তার পূর্বতন জগতটি সমাধিস্থ।"
