  StageGroup_96833_TypeText = {
    Text = "উদ্ভট রেখাচিত্র"
  },
  StageGroup_96834_Desc = {
    Text = "উন্মত্ত রেখা, বিশৃঙ্খল বিন্যাস, গ্রোটেস্ক রং, আর উন্মাদনা-জাগানো চিত্রাবলি...\nএই বিশৃঙ্খলা কি ছবির ভেতরে, নাকি ছবির বাইরে? এটি কি বাস্তব, নাকি মায়াস্বপ্ন?\nউত্তরটি সত্যিই জানতে চায়—এমন কেউ নেই।\nপ্রাণীদের কাছে, তাদের একমাত্র আকাঙ্ক্ষা সেই কার্নিভাল নিজেই।"
  },
